# Shared by the cases of this file, sourced as: . {{FIX}}/lib.sh {{CLAUDE}} {{SID}}
# own/   a copy of the launcher with its own hooks beside it (the workshop copy)
# stage/ the folder HARNESS_HOOKS_DIR names (the image's staging copy)
# proj/  a CLAUDE_PROJECT_DIR with its .claude/hooks (the plain runner of HARNESS_HOOK_RUN=0)
D=$(mktemp -d "${TMPDIR:-/tmp}/hookrun-$2-XXXXXX") || exit 1
trap 'rm -rf "$D"' EXIT
mkdir -p "$D/own" "$D/stage" "$D/proj/.claude/hooks"
cp "$1/hooks/hook-run.sh" "$D/own/hook-run.sh" || exit 1
L=$D/own/hook-run.sh
probe() { printf '#!/bin/bash\n%s\n' "$2" > "$1"; }
pre() { printf '{"session_id":"%s","hook_event_name":"PreToolUse","tool_name":"Bash","tool_input":{"command":"ls"}}' "$SID"; }
ses() { printf '{"session_id":"%s","hook_event_name":"SessionStart","source":"startup"}' "$SID"; }
sub() { printf '{"session_id":"%s","hook_event_name":"SubagentStop","stop_hook_active":false}' "$SID"; }
ups() { printf '{"session_id":"%s","hook_event_name":"UserPromptSubmit","prompt":"hi"}' "$SID"; }
# run <payload function> <name> [VAR=value ...]: prints rc=<code> out=<stdout> err=<first stderr line>
run() { local p=$1 n=$2; shift 2; local o e rc; o=$($p | env -u HARNESS_HOOKS_DIR -u HARNESS_HOOK_RUN -u CLAUDE_PROJECT_DIR "$@" bash "$L" "$n" 2>"$D/err"); rc=$?; e=$(head -n 1 "$D/err"); printf 'rc=%s out=%s err=%s' "$rc" "$o" "$e"; }
SID=$2
